function serializeQuery(pairs) {
  if (!Array.isArray(pairs)) {
    throw new TypeError("pairs must be an array");
  }

  const encoded = [];

  for (let i = 0; i < pairs.length; i++) {
    if (!Object.prototype.hasOwnProperty.call(pairs, i)) {
      throw new TypeError("sparse arrays are not allowed");
    }

    const pair = pairs[i];
    if (
      !Array.isArray(pair) ||
      pair.length !== 2 ||
      !Object.prototype.hasOwnProperty.call(pair, 0) ||
      !Object.prototype.hasOwnProperty.call(pair, 1) ||
      typeof pair[0] !== "string" ||
      typeof pair[1] !== "string"
    ) {
      throw new TypeError("each item must be a [name, value] string pair");
    }

    encoded.push([percentEncode(pair[0]), percentEncode(pair[1])]);
  }

  encoded.sort((a, b) => a[0] < b[0] ? -1 : a[0] > b[0] ? 1 :
    a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0);

  return encoded.map(pair => pair[0] + "=" + pair[1]).join("&");
}

function percentEncode(input) {
  const bytes = [];

  for (let i = 0; i < input.length; i++) {
    const unit = input.charCodeAt(i);
    let codePoint;

    if (unit >= 0xD800 && unit <= 0xDBFF) {
      if (i + 1 >= input.length) {
        throw new URIError("unpaired surrogate");
      }
      const next = input.charCodeAt(++i);
      if (next < 0xDC00 || next > 0xDFFF) {
        throw new URIError("unpaired surrogate");
      }
      codePoint = 0x10000 + ((unit - 0xD800) << 10) + (next - 0xDC00);
    } else if (unit >= 0xDC00 && unit <= 0xDFFF) {
      throw new URIError("unpaired surrogate");
    } else {
      codePoint = unit;
    }

    if (
      (codePoint >= 0x41 && codePoint <= 0x5A) ||
      (codePoint >= 0x61 && codePoint <= 0x7A) ||
      (codePoint >= 0x30 && codePoint <= 0x39) ||
      codePoint === 0x2D ||
      codePoint === 0x2E ||
      codePoint === 0x5F ||
      codePoint === 0x7E
    ) {
      bytes.push(String.fromCharCode(codePoint));
    } else if (codePoint <= 0x7F) {
      bytes.push("%" + hex(codePoint));
    } else if (codePoint <= 0x7FF) {
      bytes.push("%" + hex(0xC0 | (codePoint >> 6)));
      bytes.push("%" + hex(0x80 | (codePoint & 0x3F)));
    } else if (codePoint <= 0xFFFF) {
      bytes.push("%" + hex(0xE0 | (codePoint >> 12)));
      bytes.push("%" + hex(0x80 | ((codePoint >> 6) & 0x3F)));
      bytes.push("%" + hex(0x80 | (codePoint & 0x3F)));
    } else {
      bytes.push("%" + hex(0xF0 | (codePoint >> 18)));
      bytes.push("%" + hex(0x80 | ((codePoint >> 12) & 0x3F)));
      bytes.push("%" + hex(0x80 | ((codePoint >> 6) & 0x3F)));
      bytes.push("%" + hex(0x80 | (codePoint & 0x3F)));
    }
  }

  return bytes.join("");
}

function hex(byte) {
  return byte.toString(16).toUpperCase().padStart(2, "0");
}
